use std :: borrow :: Cow ; use derive_more :: { AsRef , Deref , From } ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use strum_macros :: { Display , EnumString } ; use url :: Url ; use crate :: { ApiKey , AuthCredential , AuthDetails , Model , Template } ; use convert_case :: { Case , Casing } ; use std :: collections :: HashMap ; use super :: * ; use std :: collections :: HashMap ; use std :: str :: FromStr ; use pretty_assertions :: assert_eq ; use super :: test_helpers :: * ; use super :: * ; impl AnyProvider { # [doc = " Returns whether this provider is configured"] pub fn is_configured (& self) -> bool { match self { AnyProvider :: Url (p) => p . is_configured () , AnyProvider :: Template (p) => p . is_configured () , } } pub fn provider_type (& self) -> & ProviderType { match self { AnyProvider :: Url (p) => & p . provider_type , AnyProvider :: Template (t) => & t . provider_type , } } pub fn id (& self) -> ProviderId { match self { AnyProvider :: Url (p) => p . id . clone () , AnyProvider :: Template (p) => p . id . clone () , } } # [doc = " Gets the response type"] pub fn response (& self) -> Option < & ProviderResponse > { match self { AnyProvider :: Url (p) => p . response . as_ref () , AnyProvider :: Template (p) => p . response . as_ref () , } } # [doc = " Gets the URL for this provider."] # [doc = ""] # [doc = " For configured providers, returns the resolved URL. For template"] # [doc = " providers with no URL parameters (i.e. a hardcoded default URL in"] # [doc = " provider.json), parses and returns the template string as a URL."] # [doc = " Returns `None` for template providers that require user-supplied URL"] # [doc = " parameters."] pub fn url (& self) -> Option < Url > { match self { AnyProvider :: Url (p) => Some (p . url () . clone ()) , AnyProvider :: Template (t) if t . url_params . is_empty () => Url :: parse (& t . url . template) . ok () , AnyProvider :: Template (_) => None , } } pub fn url_params (& self) -> & [crate :: URLParamSpec] { match self { AnyProvider :: Url (p) => & p . url_params , AnyProvider :: Template (p) => & p . url_params , } } # [doc = " Gets the authentication methods supported by this provider"] pub fn auth_methods (& self) -> & [crate :: AuthMethod] { match self { AnyProvider :: Url (p) => & p . auth_methods , AnyProvider :: Template (p) => & p . auth_methods , } } # [doc = " Consumes self and returns the configured provider if this is a URL"] # [doc = " provider with credentials"] pub fn into_configured (self) -> Option < Provider < Url > > { match self { AnyProvider :: Url (p) if p . is_configured () => Some (p) , _ => None , } } }